import json
S={'B1':'一共做两个八十宽的书柜。每块板两头各插两根木销，脚线也一样，一共十六根。','B2':'两块侧板内面朝上放平。每块拧六个连接件，顺时针拧到底，一共十二个。','B3':'一块侧板平放。脚线和底板放在这头，再把中间那块板插到中间。板子带颗粒的毛边朝后。','B4':'大锁扣放进孔里，用一字螺丝刀顺时针拧半圈，手感变紧就行。别用电钻。','B5':'第三块板插在另一头，有孔的面朝外。朝错了锁扣就放不进去。','B6':'抬起第二块侧板，慢慢压下去，所有木销和连接件都要对上，再压到底。','B7':'这一边六个锁扣，一样放到位，顺时针拧半圈。','B8':'柜子转过来，后面朝上。背板是三折的，先展开。从柜脚那头的缺口，沿两边的槽推进去，别折到。','B9':'三排，每排六个。先把带头的塞子按进背板的孔，再把圆帽按进塞子里。','B10':'把柜子立起来靠墙。先用墙螺丝把支架固定到墙上，再用木螺丝拧到柜顶。墙螺丝要按墙体自己买。','B11':'搁板销用手指按进去，高度你自己定，同一块搁板的四个要在同一高度。','B12':'把四块活动搁板放到销上，放平。两个书柜都做好了，再装门。','D1':'一共四扇门，每个书柜两扇。每扇门有一套支架，把它固定到柜顶和墙上。位置说明书只画了窄柜，请自己判断。','D2':'先定门往哪边开。照片上每个柜的两扇门向两边开，旋钮在中间。在铰链那边的侧板上装三个底板，每个两颗螺丝穿过 B 列长孔。','D3':'门背面朝上放平。一边按入三个盖片，另一边放三个铰链，每个两颗螺丝。','D4':'把铰链的卡槽挂到底板的螺丝上，往回推到位，再拧紧铰链上的螺丝。','D5':'旋钮放在门外面，从门里面用长螺丝穿过门边框拧进去。','D6':'撕下缓冲垫，贴在门背面，顶部、中部、底部各一个，一共三个，多一个留着。','D7':'门歪了就调。高度松开底板螺丝，左右先松后面的螺丝，转前面的螺丝，再拧紧后面的，前后松开后面的螺丝。四扇门都这样调到门缝一致。'}
ids=[s['id'] for s in json.load(open('steps.json',encoding='utf8'))];assert set(ids)==set(S)
open('say.js','w',encoding='utf8').write(json.dumps(S,ensure_ascii=False,separators=(',',':')))
